effect.shader:
float gmLum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
float gmHash2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec3 c = clamp(src.rgb * pow(2.0, exposureBB), 0.0, 4.0);
float l = gmLum(c);
float silver = clamp((l - 0.5) * crushContrast + 0.5, 0.0, 1.0);
silver = silver * silver * (3.0 - 2.0 * silver);
vec3 silverCol = vec3(silver);
vec3 sat = mix(vec3(l), c, silverSat);
vec3 over = mix(2.0 * sat * silverCol, 1.0 - 2.0 * (1.0 - sat) * (1.0 - silverCol), step(0.5, silverCol));
over = clamp(over, 0.0, 1.0);
float shadowW = 1.0 - smoothstep(0.0, 0.55, l);
over *= mix(vec3(1.0), vec3(0.93, 0.97, 1.06), shadowW * shadowTintAmt);
float g = gmHash2(uv * getTexSize(inputImg.size) + fract(acTime) * 37.1);
over += (g - 0.5) * grainBB * 0.35;
vec3 col = mix(src.rgb, over, strength * 0.01);
gl_FragColor = vec4(col * src.a, src.a);
}
